action_args.command:
curl -s "https://en.wikipedia.org/w/api.php?action=query&titles=List_of_municipalities_in_Oklahoma&prop=revisions&rvprop=content&format=json" 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
pages = data['query']['pages']
for page_id in pages:
    content = pages[page_id].get('revisions', [{}])[0].get('*', '')
    if content:
        lines = content.split('\n')
        # Find the table section
        in_table = False
        table_lines = []
        for i, line in enumerate(lines):
            if 'class=\"wikitable sortable\"' in line:
                in_table = True
            if in_table:
                table_lines.append(line)
                if line.strip() == '|' and i > 0 and '2020 census' in lines[i-1] if i > 0 else False:
                    pass  # continue reading
                if line.strip().startswith('|-' ) or line.strip() == '|-':
                    pass
                # End of table
                if '|}' in line and len(table_lines) > 10:
                    break
        print('\n'.join(table_lines[:200]))
"

