{"command":"curl -s "https://en.wikipedia.org/w/api.php?action=query&titles=List_of_cities_in_Oklahoma&prop=revisions&rvprop=content&rvsection=0" | python3 -c "
import sys, json
data = json.load(sys.stdin)
pages = data['query']['pages']
for page_id in pages:
    content = pages[page_id].get('revisions', [{}])[0].get('*', '')
    if content:
        print(content[:20000])
"","description":"Fetch list of cities in Oklahoma from Wikipedia API"}

