{"command":"curl -s "https://en.wikipedia.org/w/api.php?action=query&titles=List_of_municipalities_in_Oklahoma&prop=revisions&rvprop=content&format=json" 2>&1 | python3 -c "
import sys, json
data = json.load(sys.stdin)
pages = data['query']['pages']
for page_id in pages:
    content = pages[page_id].get('revisions', [{}])[0].get('*', '')
    if content:
        # Look for the cities with population data
        lines = content.split('\n')
        for i, line in enumerate(lines):
            if 'pop' in line.lower() or 'population' in line.lower():
                start = max(0, i-2)
                end = min(len(lines), i+3)
                print(f'--- Line {i} ---')
                print('\n'.join(lines[start:end]))
                print()
"","description":"Fetch list of municipalities in Oklahoma and search for population data"}

